        # 10 single documents: 9×3 + 1×2 = 29 questions, as in the classic format.
        for j in range(10):
            company=companies[(p*4+j)%32];person=names[j];event=projects[(p+j)%8];product=products[(p+j)%8];room=venues[(p+j)%8]
            fee=90+pack*10+j*5;quantity=20+pack+j;deadline=12+pack
            if j==0:
                body=f'To: {person}\nSubject: Replacement order\n\nThank you for reporting the fault with your {product}. We have arranged a replacement, which will arrive within {pack+1} business days. Please return the defective items using the prepaid label attached. A suitable alternative box is acceptable if the original packaging is no longer available.\n\nYou have {deadline} days to return the items. Contact us before that deadline if you need more time. No further payment is due.\nCustomer Services, {company}'
                items=[q('Why was the message sent?','To explain a replacement|To request a new order|To advertise a sale|To increase a price','Le courriel traite du remplacement de produits défectueux.','intent'),q('How long is allowed for the return?',f'{deadline} days|{pack+1} days|{deadline+7} days|Thirty days','Le délai de retour est distinct du délai d’arrivée du remplacement.','detail'),q('What is true of the packaging?','Another suitable box may be used|The original box is compulsory|No box is needed|A new branded box must be purchased','Le message autorise explicitement un carton de remplacement adapté.','inference')]
