                items=[q('What is the original problem?','A delivery would arrive late|A client meeting was cancelled|The event location changed|The order contained wrong products','La livraison est tardive par rapport à la préparation de l’événement.','detail'),q('Who will collect the items?','Robin|Kim|The client|The event coordinator','Robin se propose pour la récupération.', 'detail'),q('When can collection take place?','Wednesday after 14:00|Thursday before 09:00|Friday at noon|Tuesday evening','Le retrait en entrepôt est disponible mercredi après quatorze heures.','detail')]
