                documents=[('Job advertisement',f'{company} seeks an operations analyst in {city}. At least {minyears} years of analytical experience and strong spreadsheet skills are required. SQL knowledge is desirable but not essential. The successful candidate may work remotely two days a week. Selection includes an online task followed by a panel interview.'),('Interview invitation',f'Dear {person},\nYou are invited to an interview on {interview} March at 10 a.m. Please complete the online task by {taskday} March. A link will follow separately. Let us know if you require assessment adjustments.\nRecruitment team'),('Candidate reply',f'Thank you. I can attend at the proposed time. I have {experience} years of forecasting experience and use spreadsheets daily. I am currently learning SQL. The task link has arrived, and I will submit before the deadline. Please confirm whether the interview will be online or at the office.\n{person}')]
                items=[q('Which requirement does the candidate meet?','The minimum analytical experience|Advanced SQL certification|Full-time office attendance|Ten years of management',f'{experience} années de prévision dépassent le minimum de {minyears}.','synthesis','C1'),q('When is the online task due?',f'{taskday} March|{interview} March|1 March|{taskday-3} March','L’échéance du test est trois jours avant l’entretien.','detail'),q('Why may limited SQL knowledge be acceptable?','It is desirable but not essential|It is unrelated to the position|The task was cancelled|The candidate has already been hired','L’annonce distingue une préférence d’une obligation.','synthesis','C1'),q('What information is requested in the reply?','The interview format|The interview time|The task deadline|The employer’s city','Le candidat souhaite connaître le mode de l’entretien.','inference'),q('What has already arrived?','The task link|A signed contract|A travel payment|An offer letter','Le candidat confirme avoir reçu le lien.','detail')]
